using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using System.Text.Json;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;
namespace PlugInSolar {
public sealed class PvSolarConditions {
 public double[] Hoys {get;set;}public string[] Timestamps {get;set;}public double StepHours {get;set;}public double North {get;set;}public double Albedo {get;set;}public double[][] Vectors {get;set;}public double[][] DirectW {get;set;}public double[][] DiffuseW {get;set;}public double[] SunElevation {get;set;}public double[] SunAzimuth {get;set;}public string Report {get;set;}
 public void Validate(){int n=Hoys?.Length??0,p=Vectors?.Length??0;if(n==0||(p!=145&&p!=577)||StepHours!=1||Timestamps?.Length!=n||DirectW?.Length!=p||DiffuseW?.Length!=p)throw new ArgumentException("Invalid hourly Solar Conditions dimensions.");PvSeries.ValidateTime(Timestamps,StepHours,true);PvSeries.Array(Hoys,n,"Weather HOYs",0,8759);for(int i=0;i<n;i++)if(Hoys[i]!=Math.Floor(Hoys[i])||i>0&&Hoys[i]<=Hoys[i-1])throw new ArgumentException("Weather HOYs must be unique increasing hourly indices.");for(int i=0;i<p;i++){PvSeries.Array(Vectors[i],3,"Sky direction",-1,1);PvSeries.Array(DirectW[i],n,"Direct sky radiation",0);PvSeries.Array(DiffuseW[i],n,"Diffuse sky radiation",0);}PvSeries.Array(SunElevation,n,"Solar elevation",-90,90);PvSeries.Array(SunAzimuth,n,"Solar azimuth",0,360);PvSeries.Check(North,"North",-360,360);PvSeries.Check(Albedo,"Ground reflectance",0,1);}
}
public sealed class PvSolarConditionsData:PvJsonData<PvSolarConditions>{public PvSolarConditionsData(){}public PvSolarConditionsData(PvSolarConditions d):base(d){}protected override void Validate(PvSolarConditions d){d.Validate();}public override string TypeName=>"PV Solar Conditions";public override string TypeDescription=>"Hourly Radiance sky patches, solar positions, HOYs and local-standard-time metadata";public override IGH_Goo Duplicate()=>new PvSolarConditionsData(Data);public override string ToString()=>IsValid?$"Solar conditions: {Data.Hoys.Length} hours, {Data.Vectors.Length} sky patches":"Invalid solar conditions";}
public static class PvWeatherAdapter {
 public static double[] Numbers(List<IGH_Goo> values,out double[] autoHoys,out string unit){autoHoys=null;unit=null;if(values.Count==0)throw new ArgumentException("Missing radiation series.");
  if(values.Count==1){object obj=values[0].ScriptVariable();try{dynamic d=obj;var result=new List<double>();foreach(var x in d.values)result.Add(Convert.ToDouble(x));unit=Convert.ToString(d.header.unit);var h=new List<double>();foreach(var dt in d.datetimes)h.Add(Convert.ToDouble(dt.hoy));autoHoys=h.ToArray();return result.ToArray();}catch{}}
  var a=new List<double>();foreach(var g in values){double v=0;if(!g.CastTo<double>(out v))throw new ArgumentException("Connect a Ladybug hourly data collection or a numeric weather list. Use LB Deconstruct Data if an older wrapper is not supported.");a.Add(v);}return a.ToArray();
 }
 public static double[] Site(IGH_Goo goo){object obj=goo.ScriptVariable();if(obj is string text){var a=text.Split(',').Select(x=>double.Parse(x.Trim(),System.Globalization.CultureInfo.InvariantCulture)).ToArray();if(a.Length!=4)throw new ArgumentException("Text location must be latitude,longitude,UTC offset,elevation.");return a;}
  try{dynamic d=obj;return new double[]{Convert.ToDouble(d.latitude),Convert.ToDouble(d.longitude),Convert.ToDouble(d.time_zone),Convert.ToDouble(d.elevation)};}catch{}
  try{dynamic d=obj;return new double[]{Convert.ToDouble(d.Latitude),Convert.ToDouble(d.Longitude),Convert.ToDouble(d.TimeZone),Convert.ToDouble(d.Elevation)};}catch{}
  throw new ArgumentException("Connect LB Location, a supported location object, or text latitude,longitude,UTC offset,elevation (e.g. 33.749,-84.388,-5,320). UTC offset uses local standard time, not daylight saving.");
 }
}
public sealed class PvSolarConditionsComponent:GH_Component {
 bool oneBased,irradianceUnits,detailed;string cacheKey,cacheJson;
 public PvSolarConditionsComponent():base("PV Solar Conditions","Solar Conditions","Prepare hourly DNR/DHR/GHR, sun positions and time-resolved Radiance sky patches. Connect LB Import EPW or Eddy3D numeric outputs. No geometry calculation.","Plug-In Solar","02 Performance"){}
 public override Guid ComponentGuid=>new Guid("179ac02a-5165-4829-9123-c15d17912401");protected override Bitmap Icon=>Assets.Icon("sun_position");
 protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Location","Location","LB Import EPW → location. Alternative text: latitude,longitude,UTC offset hours,elevation m. Local standard time; no daylight-saving shift.",GH_ParamAccess.item);p.AddGenericParameter("Direct Normal Radiation","DNR","LB direct_normal_rad or Eddy3D Direct Normal Radiation. Hourly Wh/m²; modern Ladybug collections or numeric lists. Choose units in menu for unlabelled lists.",GH_ParamAccess.list);p.AddGenericParameter("Diffuse Horizontal Radiation","DHR","LB diffuse_horizontal_rad or Eddy3D Diffuse Horizontal Radiation, aligned with DNR.",GH_ParamAccess.list);p.AddGenericParameter("Global Horizontal Radiation","GHR","LB global_horizontal_rad or Eddy3D Global Horizontal Radiation, aligned with DNR. Validated for completeness; Ladybug-compatible ground uses sky-patch average.",GH_ParamAccess.list);int h=p.AddNumberParameter("Weather HOYs","HOY","Eddy3D Hour of Year: zero-based interval indices 0–8759. Inferred from Ladybug collection dates or full-year 8760 lists. For one-based records explicitly select menu option.",GH_ParamAccess.list);p[h].Optional=true;p.AddNumberParameter("North","North","Clockwise degrees from model +Y to true north. For Ladybug's counterclockwise numeric convention, negate its angle.",GH_ParamAccess.item,0);p.AddNumberParameter("Ground Reflectance","Reflectance","Uniform ground hemisphere reflectance, 0–1. Default 0.2.",GH_ParamAccess.item,.2);p.AddBooleanParameter("Run","Run","Generate sky conditions. False clears outputs. Radiance gendaymtx and Ladybug patch definitions are required.",GH_ParamAccess.item,false);}
 protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Solar Conditions","Conditions","Grouped hourly sky-patch direct/diffuse radiation, sun positions, HOYs, interval duration, north and ground reflectance. Connect to PV Solar Exposure.",GH_ParamAccess.item);p.AddNumberParameter("Solar Elevation","Elevation","Degrees above horizon, in weather record order; diagnostics only.",GH_ParamAccess.list);p.AddNumberParameter("Solar Azimuth","Azimuth","Degrees clockwise from true north; diagnostics only.",GH_ParamAccess.list);p.AddTextParameter("Report","Report","Source units, time convention, sky model and resolution. No separate HOY or time-step output sockets; metadata stays in Conditions.",GH_ParamAccess.item);}
 protected override void AppendAdditionalComponentMenuItems(ToolStripDropDown menu){base.AppendAdditionalComponentMenuItems(menu);Menu_AppendItem(menu,"Numeric HOYs are one-based",(s,e)=>{RecordUndoEvent("HOY convention");oneBased=!oneBased;ExpireSolution(true);},true,oneBased);Menu_AppendItem(menu,"Numeric radiation is W/m² (otherwise hourly Wh/m²)",(s,e)=>{RecordUndoEvent("Radiation units");irradianceUnits=!irradianceUnits;ExpireSolution(true);},true,irradianceUnits);Menu_AppendItem(menu,"Detailed sky (577 patches)",(s,e)=>{RecordUndoEvent("Sky resolution");detailed=!detailed;ExpireSolution(true);},true,detailed);}
 public override bool Write(GH_IO.Serialization.GH_IWriter w){w.SetBoolean("oneBased",oneBased);w.SetBoolean("irradianceUnits",irradianceUnits);w.SetBoolean("detailed",detailed);return base.Write(w);}public override bool Read(GH_IO.Serialization.GH_IReader r){if(r.ItemExists("oneBased"))oneBased=r.GetBoolean("oneBased");if(r.ItemExists("irradianceUnits"))irradianceUnits=r.GetBoolean("irradianceUnits");if(r.ItemExists("detailed"))detailed=r.GetBoolean("detailed");return base.Read(r);}
 protected override void SolveInstance(IGH_DataAccess da){try{bool run=false;da.GetData(7,ref run);if(!run){Message="Set Run = True";return;}IGH_Goo site=null;if(!da.GetData(0,ref site))return;var lists=new List<IGH_Goo>[3];var arrays=new double[3][];double[] auto=null;string detectedUnit=null;for(int i=0;i<3;i++){lists[i]=new List<IGH_Goo>();if(!da.GetDataList(i+1,lists[i]))return;arrays[i]=PvWeatherAdapter.Numbers(lists[i],out var h,out var u);if(h!=null){if(auto!=null&&!auto.SequenceEqual(h))throw new ArgumentException("Ladybug weather collection dates do not match.");auto=h;}if(u!=null){if(u!="Wh/m2"&&u!="W/m2")throw new ArgumentException("Unsupported radiation unit: "+u);if(detectedUnit!=null&&u!=detectedUnit)throw new ArgumentException("Radiation units differ between weather collections.");detectedUnit=u;}}
 var hoys=new List<double>();da.GetDataList(4,hoys);if(hoys.Count>0){if(oneBased)hoys=hoys.Select(x=>x-1).ToList();if(auto!=null&&!hoys.SequenceEqual(auto))throw new ArgumentException("Connected Weather HOYs disagree with Ladybug collection dates.");}else if(auto!=null)hoys=auto.ToList();double north=0,albedo=.2;da.GetData(5,ref north);da.GetData(6,ref albedo);var location=PvWeatherAdapter.Site(site);var request=JsonSerializer.Serialize(new{operation="solar_conditions",inputs=new{latitude=location[0],longitude=location[1],timezone=location[2],altitude=location[3],dnr=arrays[0],dhr=arrays[1],ghr=arrays[2],hoys,north,albedo,density=detailed?2:1,units=detectedUnit??(irradianceUnits?"W/m2":"Wh/m2")}});
 string response=request==cacheKey?cacheJson:PythonBridge.RunPython(request);using(var j=JsonDocument.Parse(response)){if(j.RootElement.TryGetProperty("error",out var error))throw new ArgumentException(error.GetString());var c=JsonSerializer.Deserialize<PvSolarConditions>(j.RootElement.GetProperty("outputs")[0].GetRawText());c.Validate();da.SetData(0,new PvSolarConditionsData(c));da.SetDataList(1,c.SunElevation);da.SetDataList(2,c.SunAzimuth);da.SetData(3,c.Report);Message=$"{c.Hoys.Length} hours · {c.Vectors.Length} patches";}cacheKey=request;cacheJson=response;
 }catch(Exception e){foreach(var p in Params.Output)p.ClearData();Message="";AddRuntimeMessage(GH_RuntimeMessageLevel.Error,e.Message);}}
}
}
